package com.dating.backend.matching;
import com.dating.backend.entity.*;import jakarta.persistence.EntityManager;import java.time.*;import java.util.*;import org.springframework.test.context.bean.override.mockito.MockitoBean;import static org.mockito.Mockito.when;import com.dating.backend.config.JwtUtil;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.context.WebApplicationContext;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.junit.jupiter.api.*;
import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@org.springframework.boot.test.context.SpringBootTest @org.springframework.transaction.annotation.Transactional
class PrivateMediaTest {
 @Autowired InboxService inbox; @Autowired WalletService wallet; @Autowired com.dating.backend.service.ProfileImageService photos; @Autowired com.dating.backend.service.SafetyService safety;
 @Autowired NotificationService notifications; @Autowired EntityManager em; @Autowired SocialService social; @Autowired DailyMatchService daily; @Autowired MatchPreferenceService preferences;
 @MockitoBean DailyMatchSchedule schedule;
 User a,b,c; LocalDate day=LocalDate.of(2026,10,21);
 @BeforeEach void setup(){time("2026-10-21T10:00:00");a=person("a","MALE");b=person("b","FEMALE");c=person("c","MALE");preferences.save(a.getEmail(),new MatchPreferenceService.Conditions(null,null,"ANY","ANY","ANY","ANY","ANY"));known(a,b);var w=new CreditWallet();w.setUserId(a.getId());w.setBalance(100);em.persist(w);}
 void time(String s){when(schedule.current()).thenReturn(DailyMatchSchedule.at(LocalDateTime.parse(s).atZone(ZoneId.of("Asia/Seoul")).toInstant()));}
 User person(String name,String gender){var u=User.builder().email(name+"@social.test").nickname(name).provider("LOCAL").status("ACTIVE").build();em.persist(u);em.persist(UserProfile.builder().userId(u.getId()).region("서울 강남구").mbti("ESFJ").build());em.persist(UserVerification.builder().userId(u.getId()).gender(gender).birthDate(LocalDate.of(1995,1,1)).build());em.persist(UserProfileImage.builder().userId(u.getId()).imageUrl("/uploads/test.jpg").imageOrder(0).isMain(true).build());return u;}
 void known(User x,User y){var card=new DailyMatchCard();card.setOwnerId(x.getId());card.setCycleDay(day);card.setSlot(0);card.setCandidateId(y.getId());card.setRevealedAt(Instant.now());em.persist(card);}
 SocialService.DirectRequest request(){return new SocialService.DirectRequest(b.getId(),"안녕하세요",UUID.randomUUID().toString(),10);}
 String ownedPhoto(Long owner){try{var dir=java.nio.file.Path.of("build/test-uploads/profile");java.nio.file.Files.createDirectories(dir);String name="user-"+owner+"-"+UUID.randomUUID()+".jpg";var file=dir.resolve(name);java.nio.file.Files.write(file,new byte[]{1});testFiles.add(file);return "/uploads/profile/"+name;}catch(Exception e){throw new RuntimeException(e);}}
 java.util.List<java.nio.file.Path> testFiles=new java.util.ArrayList<>();
 @AfterEach void removeTestFiles()throws Exception{for(var file:testFiles)java.nio.file.Files.deleteIfExists(file);}

 @Autowired PrivateMediaService media;@Autowired JwtUtil jwt;@Autowired WebApplicationContext context;
 String first,second;MockMvc mvc;
 @BeforeEach void mediaSetup(){mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();first=ownedPhoto(b.getId());second=ownedPhoto(b.getId());em.createQuery("update UserProfileImage i set i.imageUrl=:url where i.userId=:id").setParameter("url",first).setParameter("id",b.getId()).executeUpdate();em.persist(UserProfileImage.builder().userId(b.getId()).imageUrl(second).imageOrder(1).isMain(false).build());em.flush();}
 String relative(String url){return url.substring("/uploads/".length());}
 @Test void rawPhotoUrlAndMediaApiRequireAuthentication()throws Exception{mvc.perform(get(first)).andExpect(status().isForbidden());mvc.perform(get("/api/media/"+relative(first))).andExpect(status().isForbidden());}
 @Test void knownMemberFirstPhotoWorksButSecondDeniedAtBothRoutes()throws Exception{String token=jwt.createToken(a.getEmail());mvc.perform(get(first).header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get(second).header("Authorization","Bearer "+token)).andExpect(status().isNotFound());mvc.perform(get("/api/media/"+relative(second)).header("Authorization","Bearer "+token)).andExpect(status().isNotFound());assertNotNull(media.read(b.getEmail(),relative(second)));}
 @Test void strangersHiddenCardsAndBlockCannotReadKnownUrl(){assertThrows(Exception.class,()->media.read(c.getEmail(),relative(first)));em.createQuery("update DailyMatchCard c set c.revealedAt=null where c.ownerId=:id").setParameter("id",a.getId()).executeUpdate();assertThrows(Exception.class,()->media.read(a.getEmail(),relative(first)));em.createQuery("update DailyMatchCard c set c.revealedAt=:now where c.ownerId=:id").setParameter("now",java.time.Instant.now()).setParameter("id",a.getId()).executeUpdate();social.block(a.getEmail(),b.getId());assertThrows(Exception.class,()->media.read(a.getEmail(),relative(first)));assertThrows(Exception.class,()->social.profile(a.getEmail(),b.getId()));}
 @Test void reportedSuspendedAndDeletedMembersPhotosDenied(){em.persist(UserReport.builder().reporterUserId(a.getId()).reportedUserId(b.getId()).reasonCode("OTHER").detail("test").build());assertThrows(Exception.class,()->media.read(a.getEmail(),relative(first)));b.setStatus("SUSPENDED");assertThrows(Exception.class,()->media.read(b.getEmail(),relative(first)));b.setStatus("DELETED");assertThrows(Exception.class,()->media.read(b.getEmail(),relative(first)));}
 @Test void cannotRegisterOtherMembersOrExternalPhotos(){var r=new com.dating.backend.dto.UserProfileImageRequest();r.setImageOrder(1);r.setIsMain(false);r.setImageUrl(second);assertThrows(Exception.class,()->photos.saveMyImage(a.getEmail(),r));r.setImageUrl("https://example.com/photo.jpg");assertThrows(Exception.class,()->photos.saveMyImage(a.getEmail(),r));assertThrows(Exception.class,()->media.path("profile/../../application.yml"));}
 @Test void duplicatePhotoDoesNotIncreaseAllowance(){var url=ownedPhoto(a.getId());var r=new com.dating.backend.dto.UserProfileImageRequest();r.setImageOrder(1);r.setIsMain(false);r.setImageUrl(url);photos.saveMyImage(a.getEmail(),r);r.setImageOrder(2);assertThrows(Exception.class,()->photos.saveMyImage(a.getEmail(),r));}
 @Autowired ProfileModeration moderation;
 @Test void unreviewedReplacementAndOldApprovedFileAreProtected(){moderation.beforeEdit(b);var replacement=ownedPhoto(b.getId());em.createQuery("update UserProfileImage i set i.imageUrl=:url where i.userId=:id and i.isMain=true").setParameter("url",replacement).setParameter("id",b.getId()).executeUpdate();assertNotNull(media.read(a.getEmail(),relative(first)));assertThrows(Exception.class,()->media.read(a.getEmail(),relative(replacement)));moderation.decide(b.getId(),b.getProfileRevision(),true,"approved");assertNotNull(media.read(a.getEmail(),relative(replacement)));assertThrows(Exception.class,()->media.read(a.getEmail(),relative(first)));}
 @Test void ownPhotoApprovalAndRemovalControlPhotoAllowance(){var r=new com.dating.backend.dto.UserProfileImageRequest();r.setImageOrder(1);r.setImageUrl(ownedPhoto(a.getId()));r.setIsMain(false);photos.saveMyImage(a.getEmail(),r);assertThrows(Exception.class,()->media.read(a.getEmail(),relative(second)));moderation.decide(a.getId(),a.getProfileRevision(),true,"approved");assertNotNull(media.read(a.getEmail(),relative(second)));Long id=em.createQuery("select i.id from UserProfileImage i where i.userId=:id and i.imageOrder=1",Long.class).setParameter("id",a.getId()).getSingleResult();photos.delete(a.getEmail(),id);assertThrows(Exception.class,()->media.read(a.getEmail(),relative(second)));}
 @Test void unmatchRevokesPhotoAccess(){social.like(a.getEmail(),b.getId());social.like(b.getEmail(),a.getId());social.unmatch(a.getEmail(),b.getId());assertThrows(Exception.class,()->media.read(a.getEmail(),relative(first)));}
}
